class DiscoveryIntegrationTest {
    sealed class RelayConnection : IDisposable { public TcpClient Tcp;public SslStream Tls;public string Session;public void Dispose(){Tls.Dispose();Tcp.Close();} }
    static void Require(bool value,string message){if(!value)throw new Exception(message);}
    static bool Fails(Action action){try{action();return false;}catch{return true;}}
    static void Until(Func<bool> condition,string message,int timeoutMilliseconds=8000){var watch=Stopwatch.StartNew();while(!condition()&&watch.ElapsedMilliseconds<timeoutMilliseconds)System.Threading.Thread.Sleep(25);Require(condition(),message);}
    static string RequiredEnvironment(string name){var value=Environment.GetEnvironmentVariable(name);if(String.IsNullOrWhiteSpace(value))throw new InvalidOperationException("Missing required local environment variable "+name+".");return value;}
    static string TurnUri(MediaTurnCredentials credential){return "turn:"+Uri.EscapeDataString(credential.Username)+":"+Uri.EscapeDataString(credential.Password)+"@"+credential.Host+":"+credential.Port+"?transport=udp";}
    static bool RunPhysicalTurnProbe(string uri,out string output){var executable=Environment.GetEnvironmentVariable("PEERCHAT_TURN_PROBE_EXE");if(String.IsNullOrWhiteSpace(executable))executable=Path.Combine(Environment.CurrentDirectory,"build","tests","core","voice-media-transport-test.exe");if(!File.Exists(executable))throw new FileNotFoundException("TURN infrastructure probe executable was not built.",executable);var start=new ProcessStartInfo(executable){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true};start.EnvironmentVariables["PEERCHAT_TURN_TEST_URI"]=uri;start.EnvironmentVariables["PEERCHAT_TURN_INFRASTRUCTURE"]="1";using(var process=Process.Start(start)){if(process==null)throw new InvalidOperationException("Could not start the TURN infrastructure probe.");output=process.StandardOutput.ReadToEnd()+process.StandardError.ReadToEnd();if(!process.WaitForExit(35000)){try{process.Kill();}catch{}throw new TimeoutException("TURN infrastructure probe exceeded its bounded deadline.");}return process.ExitCode==0;}}
    static void PhysicalTurnProof(){string host=RequiredEnvironment("PEERCHAT_TURN_DISCOVERY_HOST"),pin=RequiredEnvironment("PEERCHAT_TURN_DISCOVERY_PIN"),username=RequiredEnvironment("PEERCHAT_TURN_DISCOVERY_USERNAME"),password=RequiredEnvironment("PEERCHAT_TURN_DISCOVERY_PASSWORD");int port;Require(Int32.TryParse(RequiredEnvironment("PEERCHAT_TURN_DISCOVERY_PORT"),out port)&&port>0&&port<=65535,"PEERCHAT_TURN_DISCOVERY_PORT is invalid");var client=new DiscoveryClient(host,port,pin);client.Login(username,password);client.RefreshSessionInfo();string identity=client.RegisteredPublicIdentity;Require(!String.IsNullOrWhiteSpace(identity),"Authenticated discovery session did not return its registered device Peer ID. Update the discovery server to the current TURN-proof build.");var anonymous=new DiscoveryClient(host,port,pin);Require(Fails(()=>anonymous.GetMediaTurnCredentials(identity)),"Unauthenticated discovery client obtained TURN credentials");var first=client.GetMediaTurnCredentials(identity);Require(first.Transport=="udp"&&first.ExpiresUtc>DateTimeOffset.UtcNow.ToUnixTimeSeconds(),"Issuer returned invalid TURN credential metadata");Console.WriteLine("TURN issuer accepted: host="+first.Host+":"+first.Port+" transport=udp expiry="+first.ExpiresUtc+".");string output;Require(RunPhysicalTurnProbe(TurnUri(first),out output),"PeerChat-issued temporary TURN credential did not complete the relay-only probe");Require(output.Contains("turn_probe_configuration=TURN configured; transport=udp; relay-only")&&output.Contains("PASS: configured TURN/UDP selected relay pairs and carried DTLS data plus DTLS-SRTP media probes."),"TURN probe did not report relay-only DTLS/data/RTP success");Require(!output.Contains(first.Password)&&!output.Contains(TurnUri(first)),"TURN probe output exposed credential material");var invalid=new MediaTurnCredentials{Host=first.Host,Port=first.Port,Transport="udp",Username=first.Username,Password="not-a-valid-turn-password",ExpiresUtc=first.ExpiresUtc};Require(!RunPhysicalTurnProbe(TurnUri(invalid),out output),"Malformed TURN credential was accepted by coturn");var expiring=client.GetMediaTurnCredentials(identity);long waitSeconds=Math.Max(1,expiring.ExpiresUtc-DateTimeOffset.UtcNow.ToUnixTimeSeconds()+1);Console.WriteLine("TURN issuer accepted; waiting "+waitSeconds+" seconds for the temporary credential to expire.");System.Threading.Thread.Sleep(TimeSpan.FromSeconds(waitSeconds));Require(!RunPhysicalTurnProbe(TurnUri(expiring),out output),"Expired PeerChat-issued TURN credential was accepted by coturn");var fresh=client.GetMediaTurnCredentials(identity);Require(fresh.Username!=expiring.Username&&fresh.ExpiresUtc>DateTimeOffset.UtcNow.ToUnixTimeSeconds(),"Issuer did not create a fresh temporary TURN credential");Require(RunPhysicalTurnProbe(TurnUri(fresh),out output),"Fresh PeerChat-issued TURN credential did not complete the relay-only probe");var revocation=new DiscoveryClient(host,port,pin);revocation.Login(username,password);string revoked=revocation.SessionToken;revocation.Logout();Require(Fails(()=>new DiscoveryClient(host,port,pin){SessionToken=revoked}.GetMediaTurnCredentials(identity)),"Logged-out discovery session obtained new TURN credentials");client.Logout();Console.WriteLine("PASS: discovery-issued temporary TURN credentials authenticated against coturn over relay-only ICE; malformed/expired/revoked credentials were rejected and fresh reissue succeeded.");}
    static void RpcBoundaries(DiscoveryClient client){
        var history=new DiscoveryClient("unused",1,"");
        for(int i=0;i<100;i++)history.RecordRpcTiming("cache_dm_append",new string('a',32),new string('b',32),1,2,3,6,true);
        history.RecordRpcTiming("secret-operation", "secret request", "secret command",0,0,0,0,false);
        string bounded=history.RpcTimingDiagnostics;
        Require(bounded.Contains("rpc_timing_count=101 retained=32")&&bounded.Contains("operation=other")&&!bounded.Contains("secret"),"RPC timing must be bounded and redact non-identifiers");
        var json=new JavaScriptSerializer();
        Action<SslStream,Dictionary<string,object>> send=(tls,value)=>DiscoveryClient.WriteFrame(tls,Encoding.UTF8.GetBytes(json.Serialize(value)));
        Func<SslStream,Dictionary<string,object>> read=tls=>json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(DiscoveryClient.ReadFrame(tls,100000)));
        var hello=new Dictionary<string,object>{{"version",1},{"type","rpc_open"},{"sessionToken",client.SessionToken},{"publicIdentity","peer-public-fingerprint-alice-0123456789"}};
        TcpClient tcp;
        using(var tls=client.OpenAuthenticatedStream(out tcp))using(tcp){
            Require(tcp.NoDelay,"authenticated control client must disable Nagle before TLS");
            send(tls,hello);Require((string)read(tls)["type"]=="rpc_ready","RPC open");
            send(tls,new Dictionary<string,object>{{"version",1},{"type","friend_state"},{"rpcRequestId",Guid.NewGuid().ToString("N")},{"sessionToken",client.SessionToken},{"publicIdentity","peer-public-fingerprint-wrong-device-0123456789"}});
            Require(Fails(()=>read(tls)),"RPC allowed device switch");
        }
        using(var tls=client.OpenAuthenticatedStream(out tcp))using(tcp){
            send(tls,hello);read(tls);tls.ReadTimeout=20000;
            var elapsed=Stopwatch.StartNew();Require(Fails(()=>read(tls)),"RPC idle connection persisted");
            Require(elapsed.ElapsedMilliseconds>=13000&&elapsed.ElapsedMilliseconds<19000,"RPC idle deadline incorrect");
        }
        using(var tls=client.OpenAuthenticatedStream(out tcp))using(tcp){
            send(tls,hello);read(tls);tls.Write(new byte[]{0,0,0,100,123},0,5);tls.Flush();tls.ReadTimeout=20000;
            Require(Fails(()=>read(tls)),"partial RPC frame accepted");
        }
        int before=client.RpcConnectionsOpened;for(int i=0;i<80;i++)client.GetFriendState();
        Require(client.RpcConnectionsOpened-before<=2,"bounded RPC connection count regression");
        Require(client.RpcTimingDiagnostics.Contains("retained=32")&&client.RpcTimingDiagnostics.Contains("operation=friend_state")&&client.RpcTimingDiagnostics.Contains("exchange_us=")&&client.RpcTimingDiagnostics.Contains("tcp_connect_us=")&&client.RpcTimingDiagnostics.Contains("tls_auth_us="),"real authenticated RPC timings missing");
        Console.WriteLine("CONTROL_TIMING "+client.RpcTimingDiagnostics);
        Console.WriteLine("PASS: sequential RPC reuse, bounded TLS count, idle/partial-frame closure, device binding and reconnect-on-demand.");
    }
    static string CoturnPassword(string username,string secret){using(var hmac=new HMACSHA1(Encoding.UTF8.GetBytes(secret)))return Convert.ToBase64String(hmac.ComputeHash(Encoding.UTF8.GetBytes(username)));}
    static Dictionary<string,object> Admin(string pipe,string command){using(var client=new NamedPipeClientStream(".",pipe,PipeDirection.InOut)){client.Connect(2000);var encoding=new UTF8Encoding(false);var writer=new StreamWriter(client,encoding,256,true);var reader=new StreamReader(client,encoding,false,256,true);writer.WriteLine(command);writer.Flush();return new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(reader.ReadLine());}}
    static Dictionary<string,object> AdminAccounts(string pipe,string query,int offset=0,int limit=25){return Admin(pipe,"ACCOUNT_LIST "+offset+" "+limit+" "+Convert.ToBase64String(Encoding.UTF8.GetBytes(query??"")));}
    static RelayConnection Attach(DiscoveryClient client,string local,long targetAccount,string target){TcpClient tcp;var tls=client.OpenAuthenticatedStream(out tcp,true);var json=new JavaScriptSerializer();var request=new Dictionary<string,object>{{"version",1},{"type","relay_attach"},{"sessionToken",client.SessionToken},{"publicIdentity",local},{"targetAccountId",targetAccount.ToString()},{"targetPublicIdentity",target}};DiscoveryClient.WriteFrame(tls,Encoding.UTF8.GetBytes(json.Serialize(request)));var response=json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(DiscoveryClient.ReadFrame(tls)));object ok,error;if(!response.TryGetValue("ok",out ok)||!(bool)ok){response.TryGetValue("error",out error);tls.Dispose();tcp.Close();throw new InvalidOperationException(error as string??"relay_failed");}return new RelayConnection{Tcp=tcp,Tls=tls,Session=(string)response["sessionId"]};}
    static RelayConnection OpenSilentEventLease(DiscoveryClient client,string identity){TcpClient tcp;var tls=client.OpenAuthenticatedStream(out tcp,true);var json=new JavaScriptSerializer();DiscoveryClient.WriteFrame(tls,Encoding.UTF8.GetBytes(json.Serialize(new Dictionary<string,object>{{"version",1},{"type","events"},{"sessionToken",client.SessionToken},{"publicIdentity",identity},{"clientHeartbeats",true}})));var ready=json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(DiscoveryClient.ReadFrame(tls)));Require(ready.ContainsKey("ok")&&(bool)ready["ok"],"silent event lease was rejected");DiscoveryClient.WriteFrame(tls,Encoding.UTF8.GetBytes(json.Serialize(new Dictionary<string,object>{{"type","event_heartbeat"}})));return new RelayConnection{Tcp=tcp,Tls=tls};}
    static void RelayRoundTrip(DiscoveryClient left,string leftPeer,long leftTarget,string rightPeer,DiscoveryClient right,long rightTarget,string description,bool proveIdle=false){var a=Task.Run(()=>Attach(left,leftPeer,leftTarget,rightPeer));var b=Task.Run(()=>Attach(right,rightPeer,rightTarget,leftPeer));Task.WaitAll(a,b);using(var first=a.Result)using(var second=b.Result){Require(first.Tcp.ReceiveTimeout==0&&second.Tcp.ReceiveTimeout==0,description+" inherited the short discovery request timeout");Require(first.Session==second.Session&&first.Session.Length==43,description+" did not receive one bound session");byte[] prefix=Encoding.ASCII.GetBytes(first.Session),payload=Encoding.UTF8.GetBytes("opaque-inner-peer-tls-test");var frame=new byte[prefix.Length+payload.Length];Buffer.BlockCopy(prefix,0,frame,0,prefix.Length);Buffer.BlockCopy(payload,0,frame,prefix.Length,payload.Length);var read=Task.Run(()=>DiscoveryClient.ReadFrame(second.Tls,frame.Length));if(proveIdle)System.Threading.Thread.Sleep(11000);DiscoveryClient.WriteFrame(first.Tls,frame);Require(read.Wait(3000),description+" did not survive an idle interval");var received=read.Result;Require(Convert.ToBase64String(received)==Convert.ToBase64String(frame),description+" changed opaque bytes");}}
    static void PasswordDeviceBootstrap(string host,int port,string pin){
        var owner=new DiscoveryClient(host,port,pin);
        owner.Register("bootstrap-owner-7f3k","bootstrap fixture password","bootstrap-original-device-0123456789");
        var login=new DiscoveryClient(host,port,pin);login.Login("bootstrap-owner-7f3k","bootstrap fixture password");
        var json=new JavaScriptSerializer();
        Func<string,Dictionary<string,object>> bootstrap=device=>{
            TcpClient tcp;using(var tls=login.OpenAuthenticatedStream(out tcp))using(tcp){
                DiscoveryClient.WriteFrame(tls,Encoding.UTF8.GetBytes(json.Serialize(new Dictionary<string,object>{
                    {"version",1},{"type","messaging_bootstrap"},{"bootstrapVersion",1},
                    {"sessionToken",login.SessionToken},{"publicIdentity",device}})));
                return json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(DiscoveryClient.ReadFrame(tls)));
            }
        };
        const string fresh="bootstrap-fresh-device-0123456789";
        Require((string)bootstrap(fresh)["error"]=="device_account_mismatch","Unregistered device bootstrap was accepted");
        login.ReportPresence(fresh,"",0,"",0,false);
        var state=bootstrap(fresh);
        Require((bool)state["ok"]&&(bool)state["presenceLive"]&&(string)state["registeredPublicIdentity"]==fresh,
            "Password device registration did not unblock authoritative bootstrap");
        var other=new DiscoveryClient(host,port,pin);
        const string foreign="bootstrap-foreign-device-0123456789";
        other.Register("bootstrap-other-7f3k","other bootstrap fixture password",foreign);
        Require(Fails(()=>login.ReportPresence(foreign,"",0,"",0,false)),"Password session claimed another account device");
        Require((string)bootstrap(foreign)["error"]=="device_account_mismatch","Foreign device bootstrap accepted");
        login.Logout();owner.Logout();other.Logout();
        Console.WriteLine("PASS: password login registers a fresh device before bootstrap; unregistered and foreign devices fail closed.");
    }
    public static int Main(string[] args){
